import React, { useEffect, useState } from 'react';
import { api, apiRequest, getTelegramUser } from '../api';

interface DateEvent {
  message_id: string;
  text_preview: string;
  created_at: string;
  normalized_date: string | null;
  keyword: string;
}

interface Reminder {
  id: number;
  title: string;
  description: string;
  reminder_date: string;
  reminder_type: string;
  priority: string;
  is_sent: boolean;
  is_recurring: boolean;
  recurrence_pattern?: string | null;
  created_at: string;
}

const DatesReminders: React.FC = () => {
  const [events, setEvents] = useState<DateEvent[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const [newDate, setNewDate] = useState('');
  const [newTime, setNewTime] = useState('');
  const [repeat, setRepeat] = useState('none');
  const [editing, setEditing] = useState<null | Reminder>(null);

  const telegramUser = getTelegramUser();
  const requireTgId = (): string => {
    const id = telegramUser?.id?.toString();
    if (!id) throw new Error('Не найден Telegram ID');
    return id;
  };

  const loadEvents = async () => {
    setLoading(true);
    setError(null);
    try {
      const resp = await api('/messages/dates', {
        method: 'GET',
        headers: {
          'X-Telegram-User-ID': requireTgId(),
        }
      });
      if (resp.status === 'success') setEvents(resp.events || []);
    } catch (e: any) {
      setError(e?.message || 'Ошибка загрузки дат');
    } finally {
      setLoading(false);
    }
  };

  const loadReminders = async () => {
    try {
      const resp = await api('/miniapp/reminders', { method: 'GET' });
      setReminders(resp || []);
    } catch (e: any) {
      console.error(e);
    }
  };

  const createReminder = async () => {
    if (!newTitle.trim() || !newDate) return;
    setLoading(true);
    try {
      const reminderDate = new Date(`${newDate}T${newTime || '09:00'}`);
      const payload = {
        title: newTitle.trim(),
        description: newTitle.trim(),
        reminder_date: reminderDate.toISOString(),
        reminder_type: 'custom',
        priority: 'medium',
        is_recurring: repeat !== 'none',
        recurrence_pattern: repeat !== 'none' ? repeat : null,
        ai_prompt: `Напоминание: ${newTitle.trim()}`,
      };
      const created = await api('/miniapp/reminders', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-Telegram-User-ID': requireTgId() },
        body: JSON.stringify(payload),
      });
      if (created && created.id) {
        setNewTitle('');
        setNewDate('');
        setNewTime('');
        setRepeat('none');
        loadReminders();
        alert('✅ Напоминание создано');
      }
    } catch (e: any) {
      alert('❌ Ошибка создания напоминания');
    } finally {
      setLoading(false);
    }
  };

  const deleteReminder = async (id: number) => {
    if (!confirm('Удалить напоминание?')) return;
    try {
      await api(`/miniapp/reminders/${id}`, { method: 'DELETE', headers: { 'X-Telegram-User-ID': requireTgId() } });
      setReminders(reminders.filter(r => r.id !== id));
    } catch (e: any) {
      alert('❌ Ошибка удаления');
    }
  };

  const startEdit = (r: Reminder) => {
    setEditing(r);
    setNewTitle(r.title);
    const d = new Date(r.reminder_date);
    setNewDate(d.toISOString().slice(0,10));
    setNewTime(d.toISOString().slice(11,16));
    setRepeat(r.is_recurring ? (r.recurrence_pattern || 'daily') : 'none');
  };

  const saveEdit = async () => {
    if (!editing) return;
    setLoading(true);
    try {
      const payload: any = {
        title: newTitle.trim(),
        reminder_date: new Date(`${newDate}T${newTime || '09:00'}`).toISOString(),
        is_recurring: repeat !== 'none',
        recurrence_pattern: repeat !== 'none' ? repeat : null,
      };
      const updated = await api(`/miniapp/reminders/${editing.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'X-Telegram-User-ID': requireTgId() },
        body: JSON.stringify(payload),
      });
      setReminders(reminders.map(r => r.id === editing.id ? updated : r));
      setEditing(null);
      setNewTitle(''); setNewDate(''); setNewTime(''); setRepeat('none');
    } catch (e: any) {
      alert('❌ Ошибка сохранения');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadEvents();
    loadReminders();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50 p-4">
      <div className="max-w-4xl mx-auto space-y-6">
        <div className="bg-white rounded-lg shadow p-6">
          <h1 className="text-2xl font-bold text-gray-800">📅 Даты и напоминания</h1>
          <p className="text-gray-600 mt-1">Нормализованные даты из сообщений и управление напоминаниями.</p>
        </div>

        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-3">⏰ {editing ? 'Редактирование' : 'Создание'} напоминания</h2>
          <div className="grid grid-cols-1 md:grid-cols-5 gap-2">
            <input className="border rounded px-3 py-2 md:col-span-2" placeholder="Заголовок" value={newTitle} onChange={(e)=>setNewTitle(e.target.value)} />
            <input className="border rounded px-3 py-2" type="date" value={newDate} onChange={(e)=>setNewDate(e.target.value)} />
            <input className="border rounded px-3 py-2" type="time" value={newTime} onChange={(e)=>setNewTime(e.target.value)} />
            <select className="border rounded px-3 py-2" value={repeat} onChange={(e)=>setRepeat(e.target.value)}>
              <option value="none">Без повтора</option>
              <option value="daily">Ежедневно</option>
              <option value="weekly">Еженедельно</option>
              <option value="monthly">Ежемесячно</option>
              <option value="yearly">Ежегодно</option>
            </select>
          </div>
          <div className="mt-3">
            {editing ? (
              <div className="flex gap-2">
                <button onClick={saveEdit} disabled={loading || !newTitle.trim() || !newDate} className="px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 disabled:opacity-50">Сохранить</button>
                <button onClick={()=>{setEditing(null); setNewTitle(''); setNewDate(''); setNewTime(''); setRepeat('none');}} className="px-4 py-2 bg-gray-200 text-gray-800 rounded hover:bg-gray-300">Отмена</button>
              </div>
            ) : (
              <button onClick={createReminder} disabled={loading || !newTitle.trim() || !newDate} className="px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 disabled:opacity-50">Создать</button>
            )}
          </div>
        </div>

        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-xl font-semibold text-gray-800 mb-3">📋 Напоминания</h2>
          {reminders.length === 0 ? (
            <p className="text-gray-500">Нет напоминаний</p>
          ) : (
            <div className="space-y-3">
              {reminders.map((r) => (
                <div key={r.id} className="border rounded p-3">
                  <div className="flex justify-between items-start gap-3">
                    <div>
                      <div className="text-gray-800 font-medium">{r.title}</div>
                      <div className="text-xs text-gray-500">{new Date(r.reminder_date).toLocaleString('ru-RU')} • {r.reminder_type} • {r.priority}</div>
                      {r.is_recurring && <div className="text-xs text-indigo-600">Повтор: {r.recurrence_pattern}</div>}
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => startEdit(r)} className="px-3 py-1 bg-yellow-500 text-white rounded hover:bg-yellow-600">Редактировать</button>
                      <button onClick={() => deleteReminder(r.id)} className="px-3 py-1 bg-red-500 text-white rounded hover:bg-red-600">Удалить</button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default DatesReminders;


